'use strict';
(()=>{
 const reduced=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(hover: hover) and (pointer: fine)');
 const root=document.documentElement;let motion=true,sound=false,audio=null,frame=0,paintedAt=0;
 try{motion=localStorage.getItem('paktai_motion')!=='off';sound=localStorage.getItem('paktai_sound')==='on'}catch{}
 const enabled=()=>motion&&!reduced.matches;
 const progress=document.createElement('div');progress.className='scroll-progress';progress.setAttribute('aria-hidden','true');document.body.append(progress);
 const tools=document.createElement('div');tools.className='effects-tools';tools.setAttribute('role','group');tools.setAttribute('aria-label','ตัวเลือกเอฟเฟกต์');
 function button(label,action){const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=action;tools.append(b);return b}
 const soundButton=button('',()=>{sound=!sound;if(sound)clickSound();sync()});const motionButton=button('',()=>{motion=!motion;sync();restart()});const topButton=button('↑',()=>window.scrollTo({top:0,behavior:enabled()?'smooth':'auto'}));topButton.className='back-top';topButton.setAttribute('aria-label','กลับด้านบน');document.body.append(tools);
 function sync(){root.classList.toggle('motion-off',!enabled());soundButton.textContent=sound?'♫ เสียงคลิก เปิด':'♫ ลองเสียงคลิก';soundButton.setAttribute('aria-pressed',String(sound));motionButton.textContent=enabled()?'✦ เอฟเฟกต์ เปิด':'✦ เอฟเฟกต์ ปิด';motionButton.setAttribute('aria-pressed',String(enabled()));try{localStorage.setItem('paktai_motion',motion?'on':'off');localStorage.setItem('paktai_sound',sound?'on':'off')}catch{}}
 function clickSound(){if(!sound)return;try{const Context=window.AudioContext||window.webkitAudioContext;if(!Context)return;audio??=new Context();if(audio.state==='suspended')audio.resume();const osc=audio.createOscillator(),gain=audio.createGain(),time=audio.currentTime;osc.type='sine';osc.frequency.setValueAtTime(900,time);osc.frequency.exponentialRampToValueAtTime(440,time+.07);gain.gain.setValueAtTime(.035,time);gain.gain.exponentialRampToValueAtTime(.001,time+.09);osc.connect(gain);gain.connect(audio.destination);osc.start(time);osc.stop(time+.1)}catch{}}
 function scroll(){const max=document.documentElement.scrollHeight-innerHeight;progress.style.width=(max>0?scrollY/max*100:0)+'%';topButton.hidden=scrollY<180}
 addEventListener('scroll',scroll,{passive:true});addEventListener('resize',scroll,{passive:true});scroll();
 document.addEventListener('click',e=>{const target=e.target.closest('a,button');if(!target)return;if(target!==soundButton)clickSound();if(!enabled()||!e.detail)return;const ripple=document.createElement('span');ripple.className='click-ripple';ripple.setAttribute('aria-hidden','true');ripple.style.left=e.clientX+'px';ripple.style.top=e.clientY+'px';document.body.append(ripple);ripple.addEventListener('animationend',()=>ripple.remove(),{once:true})});
 document.querySelectorAll('.sample').forEach(card=>{card.addEventListener('pointermove',e=>{if(!enabled()||!fine.matches)return;const rect=card.getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),y=Math.max(0,Math.min(1,(e.clientY-rect.top)/rect.height));card.style.setProperty('--tilt-x',(4-y*8)+'deg');card.style.setProperty('--tilt-y',(x*8-4)+'deg');card.style.setProperty('--glow-x',x*100+'%');card.style.setProperty('--glow-y',y*100+'%');card.classList.add('is-hovered')});card.addEventListener('pointerleave',()=>card.classList.remove('is-hovered'));card.addEventListener('focus',()=>{if(enabled())card.classList.add('is-hovered')});card.addEventListener('blur',()=>card.classList.remove('is-hovered'))});
 const hero=document.querySelector('.hero');if(!hero){sync();return}const canvas=document.createElement('canvas');canvas.className='hero-sparkles';canvas.setAttribute('aria-hidden','true');hero.prepend(canvas);const ctx=canvas.getContext('2d');let width=0,height=0,visible=true;const stars=Array.from({length:30},(_,i)=>({x:Math.random(),y:Math.random(),r:.6+Math.random()*1.4,speed:.000006+Math.random()*.000014,phase:i*.7}));
 function resize(){width=hero.clientWidth;height=hero.clientHeight;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx?.setTransform(dpr,0,0,dpr,0,0)}
 function paint(time){frame=0;if(!enabled()||document.hidden||!visible||!ctx)return;if(time-paintedAt>32){paintedAt=time;ctx.clearRect(0,0,width,height);for(const p of stars){const x=(p.x+time*p.speed)%1*width,y=(p.y-time*p.speed*.6%1+1)%1*height;const alpha=.15+.45*(.5+.5*Math.sin(time*.001+p.phase));ctx.fillStyle='rgba(255,236,141,'+alpha+')';ctx.shadowColor='#ffdc53';ctx.shadowBlur=8;ctx.beginPath();ctx.arc(x,y,p.r,0,Math.PI*2);ctx.fill()}}frame=requestAnimationFrame(paint)}
 function restart(){cancelAnimationFrame(frame);frame=0;if(enabled()&&!document.hidden&&visible&&ctx)frame=requestAnimationFrame(paint);else ctx?.clearRect(0,0,width,height)}
 addEventListener('resize',()=>{resize();restart()},{passive:true});document.addEventListener('visibilitychange',restart);reduced.addEventListener('change',()=>{sync();restart()});if('IntersectionObserver'in window)new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;restart()}).observe(hero);resize();sync();restart();
})();
